import { Icon } from "@/registry/erbium/ui/icon";

import { Avatar, AvatarBadge, AvatarFallback, AvatarImage } from "@/registry/erbium/ui/avatar";

export default function AvatarBadgeIconExample() {
  return (
    <Avatar className="grayscale">
      <AvatarImage
        src="https://images.pexels.com/photos/1681010/pexels-photo-1681010.jpeg?auto=compress&cs=tinysrgb&w=256&h=256&fit=crop"
        alt="Sam Taylor"
      />
      <AvatarFallback>ST</AvatarFallback>
      <AvatarBadge>
        <Icon name="plus" />
      </AvatarBadge>
    </Avatar>
  );
}

import AvatarBadgeIconExample from "../examples/avatar-badge-icon";

const Example = () => <AvatarBadgeIconExample />;

export default Example;
